mapper.update:
UPDATE partner SET name = #{name}, chip_bg = #{chipBg}, chip_fg = #{chipFg}, homepage_url = #{homepageUrl},
                   exposed = #{exposed}, sort_order = #{sortOrder}, updated_at = now()
WHERE code = #{code}

mapper.select:
SELECT id, partner_code, url_type, url, label, sort_order
FROM collect_url WHERE partner_code = #{partnerCode}
ORDER BY CASE url_type WHEN 'POSTPAID' THEN 1 WHEN 'PREPAID' THEN 2 ELSE 3 END, sort_order, id

SELECT id, partner_code, url_type, url, label, sort_order
FROM collect_url
WHERE url = #{url}
  AND id <> #{excludeId}
  AND (url_type = #{urlType}
       OR url_type IN ('POSTPAID', 'PREPAID'))
LIMIT 1

mapper.update:
UPDATE collect_url SET url_type = #{urlType}, url = #{url}, label = #{label}, sort_order = #{sortOrder},
                       updated_at = now()
WHERE id = #{id}

mapper.select:
SELECT id, partner_code, url, label, status FROM partner_tab
WHERE partner_code = #{partnerCode}
ORDER BY status, first_seen_on DESC, id

SELECT r.id, r.job_id, j.trigger, j.attempt, r.partner_code, pt.name AS partner_name, r.url_type, r.run_on,
       r.result, r.url_count, r.collected_count, r.new_count, r.changed_count, r.ended_count, r.message,
       r.started_at, r.finished_at
FROM crawl_run r
JOIN crawl_job j ON j.id = r.job_id
JOIN partner pt ON pt.code = r.partner_code
WHERE r.run_on BETWEEN #{from} AND #{to}
  AND r.partner_code = #{partnerCode}
  AND r.url_type = #{urlType}
  AND r.result = #{result}
ORDER BY r.finished_at DESC, r.id DESC
LIMIT #{limit}
